SELECT COUNT(1) FROM sys_user
WHERE username = #{username} AND del_flag = '0'
AND user_id <> #{excludeId}

SELECT COUNT(1) FROM sys_user
WHERE phone = #{phone} AND phone <> '' AND del_flag = '0'
AND user_id <> #{excludeId}

SELECT ur.user_id FROM sys_user_role ur
INNER JOIN sys_user u ON u.user_id = ur.user_id AND u.del_flag = '0'
WHERE ur.role_id = #{roleId}

SELECT user_id FROM sys_user
WHERE del_flag = '0' AND dept_id IN
#{id}
